layer.css:
@import url("https://fonts.googleapis.com/css?family=Mulish:400,400italic,700,700italic%7cNoto%20Serif%20SC:400,400italic,700,700italic%7c&display=swap");
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgb(255, 243, 243); border-left: 6px solid rgb(255, 208, 208); border-radius: 10px; box-shadow: rgb(255, 247, 247) 0px 1px 3px 0px, rgb(255, 247, 247) 0px 5px 16px 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 12px; padding-bottom: 0px; padding-left: 12px; transition: 0.3s; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: rgb(136, 136, 136); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-radius: 10px; transition: 0.7s cubic-bezier(0.215, 0.61, 0.355, 1) }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: #ec5151; border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(255, 82, 82); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 40px; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: 2px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-surface); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: rgba(0, 0, 0, 0.7) 0px 0px 8px; transition: transform 0.7s cubic-bezier(0.215, 0.61, 0.355, 1) }
[data-ryt="category"], [data-ryt="tags"] li { color: #ec5151; border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(255, 82, 82); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: 0.3s }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 15px; font-weight: 400; font-style: normal; line-height: 2.133; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="cover"] { border-radius: 0px }
[data-ryt="rec-card"] [data-ryt="title"] { color: #ec5151; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 25px; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: 1px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(255, 82, 82); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.3s }
[data-ryt="cover"]:hover { transform: scale(1.05) }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { opacity: 1; color: #ff0000 }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="pitch"]:hover { box-shadow: 0 2px 5px #fff7f7, 0 8px 22px #fff7f7 }
